('pedagogy_test_content', '{\"version\":\"2026.1\",\"title\":\"Pedagogy Competency Assessment\",\"subtitle\":\"Karya Bangsa School · Teacher Candidate Pedagogical Examination\",\"durationMinutes\":45,\"passingScorePercent\":75,\"domains\":[{\"id\":\"planning\",\"name\":\"Instructional Planning & Curriculum\",\"description\":\"Formulating backward-design learning objectives, pedagogical alignment, and scaffolding.\"},{\"id\":\"management\",\"name\":\"Classroom Management & Environment\",\"description\":\"Cultivating positive classroom climate, restorative discipline, and proactive engagement.\"},{\"id\":\"methodology\",\"name\":\"Teaching Methodologies & PCK\",\"description\":\"Inquiry-based pedagogy, active learning, conceptual mastery, and educational technology.\"},{\"id\":\"assessment\",\"name\":\"Assessment & Differentiation\",\"description\":\"Formative evaluation techniques, constructive feedback, and multi-tiered accommodations.\"}],\"questions\":[{\"id\":\"ped-1\",\"domain\":\"planning\",\"domainLabel\":\"Instructional Planning & Curriculum\",\"scenario\":\"During a unit on environmental sustainability, you notice several students understand vocabulary words in isolation but struggle to explain cause-and-effect relationships in ecosystems.\",\"prompt\":\"Which instructional planning strategy best scaffolds conceptual understanding according to backward design principles?\",\"options\":[\"Provide a vocabulary matching quiz at the start of every session.\",\"Design a guided concept map linking ecosystem variables before requiring the synthesis explanation.\",\"Assign an independent research project to be completed at home over the weekend.\",\"Move forward to the next textbook chapter to maintain the pacing guide schedule.\"],\"correctIndex\":1,\"rationale\":\"Concept mapping provides visual scaffolding that explicitly articulates causal relationships, helping learners bridge the gap from rote terminology to systemic comprehension.\"},{\"id\":\"ped-2\",\"domain\":\"planning\",\"domainLabel\":\"Instructional Planning & Curriculum\",\"scenario\":\"A 10th-grade teacher needs to formulate an objective for an argumentative writing module aligned with Bloom\'s Revised Taxonomy.\",\"prompt\":\"Which objective is stated in specific, measurable, and higher-order cognitive terms?\",\"options\":[\"Students will appreciate the importance of persuasive rhetoric in public speaking.\",\"Students will understand the core components of counterarguments in editorial texts.\",\"Students will evaluate two contrasting editorial claims and synthesize an evidence-backed rebuttal.\",\"Students will read three selected essays and memorize common logical fallacies.\"],\"correctIndex\":2,\"rationale\":\"Evaluating opposing arguments and synthesizing a cohesive rebuttal targets higher-order thinking (Evaluation & Synthesis) and can be directly observed and assessed.\"},{\"id\":\"ped-3\",\"domain\":\"management\",\"domainLabel\":\"Classroom Management & Environment\",\"scenario\":\"During group collaboration activities, two students frequently speak over their peers and dominate decision-making, leaving quieter team members disengaged.\",\"prompt\":\"Which proactive classroom management intervention is most constructive?\",\"options\":[\"Immediately disband the group and assign individual textbook worksheets.\",\"Establish structured cooperative learning roles (e.g., Facilitator, Timekeeper, Scribe, Reporter) with clear accountability protocols.\",\"Publicly reprimand the dominant students in front of the classroom.\",\"Allow the group to resolve the conflict without teacher intervention to foster autonomy.\"],\"correctIndex\":1,\"rationale\":\"Assigning structured cooperative roles distributes responsibility equitably, ensuring every student has an explicit, valued contribution while mitigating dominant behavior.\"},{\"id\":\"ped-4\",\"domain\":\"management\",\"domainLabel\":\"Classroom Management & Environment\",\"scenario\":\"A student repeatedly arrives five minutes late to first-period class, disrupting opening instructional routines and bell work.\",\"prompt\":\"Applying restorative practices and effective classroom communication, what is the teacher\'s best initial step?\",\"options\":[\"Send the student directly to the administrative office for formal detention.\",\"Lock the classroom door exactly when the bell rings to discourage tardiness.\",\"Conduct a private, empathetic conversation after class to understand underlying causes and establish a supportive morning plan.\",\"Deduct five participation points from the student\'s grade each time they are late.\"],\"correctIndex\":2,\"rationale\":\"Restorative approaches prioritize understanding the root problem (e.g., family circumstances, transit issues) through respectful private dialogue before punitive measures.\"},{\"id\":\"ped-5\",\"domain\":\"methodology\",\"domainLabel\":\"Teaching Methodologies & PCK\",\"scenario\":\"A science teacher introduces heat transfer. Instead of presenting lecture slides with definitions of conduction, convection, and radiation, the teacher provides hands-on stations with ice, warm water, and heat lamps.\",\"prompt\":\"What pedagogical model does this instructional sequence exemplify?\",\"options\":[\"Direct instruction and behavioral drill.\",\"Inquiry-based experiential learning using the 5E Instructional Model (Engage/Explore first).\",\"Rote memorization and reproductive recall.\",\"Passive auditory demonstration.\"],\"correctIndex\":1,\"rationale\":\"Providing hands-on observation before introducing formal definitions aligns with inquiry-based learning, allowing students to construct schemas from empirical observations.\"},{\"id\":\"ped-6\",\"domain\":\"methodology\",\"domainLabel\":\"Teaching Methodologies & PCK\",\"scenario\":\"You are teaching a mixed-ability cohort where some students are English language learners (ELLs) and struggle with dense academic texts.\",\"prompt\":\"Which pedagogical accommodation provides linguistic access without lowering cognitive rigor?\",\"options\":[\"Exempt ELL students from reading tasks and give them coloring activities instead.\",\"Provide dual-language glossaries, structured sentence stems, and multimodal graphic organizers.\",\"Require students to translate the entire chapter verbatim into their native language.\",\"Lower the grading scale solely for language learners without instructional modifications.\"],\"correctIndex\":1,\"rationale\":\"Multimodal organizers and sentence frames scaffold the academic language demands while preserving the high-level cognitive expectations of the lesson.\"},{\"id\":\"ped-7\",\"domain\":\"assessment\",\"domainLabel\":\"Assessment & Differentiation\",\"scenario\":\"At the conclusion of a math lesson on quadratic functions, you want to gauge student readiness for tomorrow\'s applied word problems within the last 5 minutes of class.\",\"prompt\":\"Which formative assessment tool is most efficient and informative for next-day lesson planning?\",\"options\":[\"An unannounced 30-minute closed-book quiz.\",\"A 1-question digital or paper Exit Ticket targeting the core misconception.\",\"Assigning 50 practice problems for homework without reviewing them.\",\"Asking the whole class \'Does everyone understand?\' and moving on if nobody raises a hand.\"],\"correctIndex\":1,\"rationale\":\"An Exit Ticket yields immediate, individualized diagnostic data that reveals specific misconceptions, allowing the educator to adapt instruction for the next lesson.\"},{\"id\":\"ped-8\",\"domain\":\"assessment\",\"domainLabel\":\"Assessment & Differentiation\",\"scenario\":\"A teacher notices that student essay submissions receive low scores primarily because students don\'t understand how their work is evaluated.\",\"prompt\":\"Which assessment practice best empowers student metacognition and self-regulated learning?\",\"options\":[\"Keep grading rubrics confidential until after the final grades are submitted.\",\"Co-construct or unpack analytical rubrics with students and facilitate structured peer evaluation prior to final submission.\",\"Rely exclusively on holistic percentage grades without explanatory comments.\",\"Allow only the top-performing students to review their rubric feedback.\"],\"correctIndex\":1,\"rationale\":\"Transparent analytical rubrics with pre-submission peer evaluation illuminate criteria for success, fostering metacognitive awareness and actionable revision.\"},{\"id\":\"ped-9\",\"domain\":\"planning\",\"domainLabel\":\"Instructional Planning & Curriculum\",\"scenario\":\"An interdisciplinary unit connects history and literature. The teacher wants to ensure students synthesize historical context with character motivations.\",\"prompt\":\"Which planning tool best ensures vertical and horizontal curricular coherence?\",\"options\":[\"Isolated daily lesson plans with no overarching thematic framework.\",\"A cross-curricular unit roadmap aligning common thematic benchmarks and shared rubrics.\",\"Using two completely unrelated textbooks without coordination between department teachers.\",\"Grading students solely on grammar mechanics rather than historical analysis.\"],\"correctIndex\":1,\"rationale\":\"A cross-curricular roadmap aligns standards across disciplines, enabling coherent thematic exploration and authentic transfer of concepts.\"},{\"id\":\"ped-10\",\"domain\":\"management\",\"domainLabel\":\"Classroom Management & Environment\",\"scenario\":\"During classroom discussions, students are hesitant to share hypotheses for fear of being wrong or judged by peers.\",\"prompt\":\"What teacher strategy actively cultivates psychological safety and a growth mindset?\",\"options\":[\"Praise only completely correct answers and ignore incorrect responses.\",\"Frame incorrect hypotheses as valuable learning data and praise constructive risk-taking and reasoning processes.\",\"Call only on volunteers who always know the answers to keep discussion moving quickly.\",\"Penalize students who make errors during formative classroom discussions.\"],\"correctIndex\":1,\"rationale\":\"Normalizing errors as informative steps in scientific and pedagogical inquiry establishes psychological safety and reinforces a growth mindset.\"},{\"id\":\"ped-11\",\"domain\":\"methodology\",\"domainLabel\":\"Teaching Methodologies & PCK\",\"scenario\":\"A teacher wants students to analyze primary source historical documents rather than just reading a summary.\",\"prompt\":\"Which instructional technique best supports critical historical literacy?\",\"options\":[\"Have students copy verbatim paragraphs from the primary documents into notebooks.\",\"Use the Sourcing, Contextualization, and Corroboration protocol (Stanford History Education Group approach).\",\"Instruct students to skim the document in 60 seconds and guess the author\'s intent.\",\"Deliver a monologue explaining the document while students sit silently.\"],\"correctIndex\":1,\"rationale\":\"The Sourcing, Contextualization, and Corroboration heuristic trains students in authentic disciplinary literacy and critical document evaluation.\"},{\"id\":\"ped-12\",\"domain\":\"assessment\",\"domainLabel\":\"Assessment & Differentiation\",\"scenario\":\"A teacher receives diagnostic assessment data showing three distinct readiness tiers in reading comprehension within the same classroom.\",\"prompt\":\"How should differentiated instruction be organized to serve all tiers equitably?\",\"options\":[\"Teach exclusively to the middle tier and let the other tiers self-accommodate.\",\"Provide tiered reading texts with identical essential questions, supplemented by targeted small-group guided instruction.\",\"Segregate struggling students permanently in a separate room.\",\"Give advanced students double homework while giving struggling students no tasks.\"],\"correctIndex\":1,\"rationale\":\"Tiered texts with common essential questions ensure all students engage with core concepts at their instructional reading level, supported by flexible small-group coaching.\"}]}', '2026-09-05T05:40:19.699Z'),
('questions_content', '{\"id\":\"ielts-placement-bank-2026\",\"version\":\"2026.3\",\"title\":\"KBS Comprehensive Placement Assessment\",\"durationMinutes\":70,\"audience\":\"Candidate Teachers / Academic Faculty & Students\",\"sourceNote\":\"Final Placement Test Structure: Section 1 Grammar & Vocabulary (50 questions, 30 mins), Section 2 Writing Placement Test (User selects 1 question from 5 topics to write 1 Essay, 20 mins), Section 3 Oral Placement Test (21 questions, 20 mins).\",\"sections\":[{\"id\":\"grammar-vocabulary\",\"durationMinutes\":30,\"instructions\":\"Choose the correct letter for each question (50 questions · 30 minutes).\",\"questions\":[{\"id\":\"g-1\",\"type\":\"multiple-choice\",\"prompt\":\"I’m 18 and my brother is 20, so he’s _____ me.\",\"options\":[\"the oldest of\",\"older than\",\"as old as\"],\"answer\":\"older than\"},{\"id\":\"g-2\",\"type\":\"multiple-choice\",\"prompt\":\"Carl’s very _____. He’s never late, and he never forgets to do things.\",\"options\":[\"reliable\",\"patient\",\"strict\"],\"answer\":\"reliable\"},{\"id\":\"g-3\",\"type\":\"multiple-choice\",\"prompt\":\"We stayed in a lovely villa _____ the sea.\",\"options\":[\"it overlooks\",\"overlooked\",\"overlooking\"],\"answer\":\"overlooking\"},{\"id\":\"g-4\",\"type\":\"multiple-choice\",\"prompt\":\"Not until the 1980s _____ for the average person to own a computer.\",\"options\":[\"it was possible\",\"was it possible\",\"was possible\"],\"answer\":\"was it possible\"},{\"id\":\"g-5\",\"type\":\"multiple-choice\",\"prompt\":\"Jan _____ her arm on a hot iron.\",\"options\":[\"broke\",\"burned\",\"sprained\"],\"answer\":\"burned\"},{\"id\":\"g-6\",\"type\":\"multiple-choice\",\"prompt\":\"Tomorrow’s a holiday, so we _____ go to work.\",\"options\":[\"have to\",\"mustn’t\",\"don’t have to\"],\"answer\":\"don’t have to\"},{\"id\":\"g-7\",\"type\":\"multiple-choice\",\"prompt\":\"I usually _____ swimming at least once a week.\",\"options\":[\"go\",\"do\",\"play\"],\"answer\":\"go\"},{\"id\":\"g-8\",\"type\":\"multiple-choice\",\"prompt\":\"My friend Siena _____ to Russia last year.\",\"options\":[\"went\",\"has gone\",\"has been\"],\"answer\":\"went\"},{\"id\":\"g-9\",\"type\":\"multiple-choice\",\"prompt\":\"This is _____ area, with a lot of factories and warehouses.\",\"options\":[\"an agricultural\",\"an industrial\",\"a residential\"],\"answer\":\"an industrial\"},{\"id\":\"g-10\",\"type\":\"multiple-choice\",\"prompt\":\"If I ........ well in my exams, I _____ to university.\",\"options\":[\"will do; will go\",\"will do; go\",\"do; will go\"],\"answer\":\"do; will go\"},{\"id\":\"g-11\",\"type\":\"multiple-choice\",\"prompt\":\"She was so upset that she burst ........ tears.\",\"options\":[\"into\",\"out\",\"with\"],\"answer\":\"into\"},{\"id\":\"g-12\",\"type\":\"multiple-choice\",\"prompt\":\"Where did you go _____ holiday last year?\",\"options\":[\"for\",\"on\",\"to\"],\"answer\":\"on\"},{\"id\":\"g-13\",\"type\":\"multiple-choice\",\"prompt\":\"Ocean currents _____ play an important part in regulating global climate.\",\"options\":[\"are known to\",\"thought to\",\"are believed that they\"],\"answer\":\"are known to\"},{\"id\":\"g-14\",\"type\":\"multiple-choice\",\"prompt\":\"My cousin _____ getting a job in Bahrain.\",\"options\":[\"would like\",\"is planning\",\"is thinking of\"],\"answer\":\"is thinking of\"},{\"id\":\"g-15\",\"type\":\"multiple-choice\",\"prompt\":\"I can’t _____ your hair, because I haven’t got any scissors.\",\"options\":[\"brush\",\"cut\",\"wash\"],\"answer\":\"cut\"},{\"id\":\"g-16\",\"type\":\"multiple-choice\",\"prompt\":\"I wish I _____ have an exam tomorrow!\",\"options\":[\"don’t\",\"didn’t\",\"won’t\"],\"answer\":\"didn’t\"},{\"id\":\"g-17\",\"type\":\"multiple-choice\",\"prompt\":\"The government plans to _____ taxes on sales of luxury items.\",\"options\":[\"increase\",\"expand\",\"go up\"],\"answer\":\"increase\"},{\"id\":\"g-18\",\"type\":\"multiple-choice\",\"prompt\":\"When I first moved to Hong Kong, life in a different country was very strange, but now I’m used _____ here.\",\"options\":[\"living\",\"to live\",\"to living\"],\"answer\":\"to living\"},{\"id\":\"g-19\",\"type\":\"multiple-choice\",\"prompt\":\"There _____ milk in the fridge.\",\"options\":[\"is some\",\"are some\",\"is a\"],\"answer\":\"is some\"},{\"id\":\"g-20\",\"type\":\"multiple-choice\",\"prompt\":\"Criminals are people who are guilty of _____ the law.\",\"options\":[\"breaking\",\"cheating\",\"committing\"],\"answer\":\"breaking\"},{\"id\":\"g-21\",\"type\":\"multiple-choice\",\"prompt\":\"Why on earth isn’t Josh here yet? ........ for him for over an hour!\",\"options\":[\"I’m waiting\",\"I’ve been waiting\",\"I’ve waited\"],\"answer\":\"I’ve been waiting\"},{\"id\":\"g-22\",\"type\":\"multiple-choice\",\"prompt\":\"“It’s pouring down, and it’s freezing.” What are the weather conditions?\",\"options\":[\"high winds and snow\",\"heavy rain and cold temperatures\",\"thick cloud but quite warm\"],\"answer\":\"heavy rain and cold temperatures\"},{\"id\":\"g-23\",\"type\":\"multiple-choice\",\"prompt\":\"_____ feeling OK? You don’t look very well.\",\"options\":[\"Do you\",\"You are\",\"Are you\"],\"answer\":\"Are you\"},{\"id\":\"g-24\",\"type\":\"multiple-choice\",\"prompt\":\"Daniel’s hair is getting far too long; he should _____ soon.\",\"options\":[\"cut it\",\"have cut it\",\"have it cut\"],\"answer\":\"have it cut\"},{\"id\":\"g-25\",\"type\":\"multiple-choice\",\"prompt\":\"Mandy works for a computer software company. She got _____ recently, and so now she’s an area manager.\",\"options\":[\"made redundant\",\"promoted\",\"a raise\"],\"answer\":\"promoted\"},{\"id\":\"g-26\",\"type\":\"multiple-choice\",\"prompt\":\"I can’t hear you – it’s _____ noisy in here.\",\"options\":[\"too\",\"too much\",\"too many\"],\"answer\":\"too\"},{\"id\":\"g-27\",\"type\":\"multiple-choice\",\"prompt\":\"Jamal has just sent me _____ to arrange plans for this weekend.\",\"options\":[\"a blog\",\"an email\",\"a website\"],\"answer\":\"an email\"},{\"id\":\"g-28\",\"type\":\"multiple-choice\",\"prompt\":\"I promise I’ll call you as soon as ........ .\",\"options\":[\"I arrive\",\"I arrived\",\"I’ll arrive\"],\"answer\":\"I arrive\"},{\"id\":\"g-29\",\"type\":\"multiple-choice\",\"prompt\":\"Photographers and designers need to be very ........ .\",\"options\":[\"creative\",\"fit\",\"annoying\"],\"answer\":\"creative\"},{\"id\":\"g-30\",\"type\":\"multiple-choice\",\"prompt\":\"The global financial crisis, _____ is forcing lots of small businesses to close, does not look set to end soon.\",\"options\":[\"it\",\"that\",\"which\"],\"answer\":\"which\"},{\"id\":\"g-31\",\"type\":\"multiple-choice\",\"prompt\":\"There _____ a terrible accident if the pilot hadn’t reacted so quickly.\",\"options\":[\"had been\",\"was\",\"would have been\"],\"answer\":\"would have been\"},{\"id\":\"g-32\",\"type\":\"multiple-choice\",\"prompt\":\"“Are you ready to order?”\\n“Not yet – I’m still looking at the _____”\",\"options\":[\"bill\",\"menu\",\"service\"],\"answer\":\"menu\"},{\"id\":\"g-33\",\"type\":\"multiple-choice\",\"prompt\":\"“My job is never boring.”\\nThe speaker’s job is always ........ .\",\"options\":[\"interesting\",\"popular\",\"difficult\"],\"answer\":\"interesting\"},{\"id\":\"g-34\",\"type\":\"multiple-choice\",\"prompt\":\"I’ve been working here _____ about the last two years.\",\"options\":[\"during\",\"for\",\"since\"],\"answer\":\"for\"},{\"id\":\"g-35\",\"type\":\"multiple-choice\",\"prompt\":\"“It leaves from Platform 2 at 4.15.” The speaker is talking about ........ .\",\"options\":[\"an airline flight\",\"a train\",\"a taxi\"],\"answer\":\"a train\"},{\"id\":\"g-36\",\"type\":\"multiple-choice\",\"prompt\":\"I went to a lovely _____ last Saturday. The bride was my best friend when we were at school.\",\"options\":[\"anniversary\",\"marriage\",\"wedding\"],\"answer\":\"wedding\"},{\"id\":\"g-37\",\"type\":\"multiple-choice\",\"prompt\":\"“I’ve got a headache.”\\n“Maybe you _____ to take an aspirin.”\",\"options\":[\"should\",\"ought\",\"don’t\"],\"answer\":\"ought\"},{\"id\":\"g-38\",\"type\":\"multiple-choice\",\"prompt\":\"The patient had an _____ to insert metal pins in his broken leg.\",\"options\":[\"injection\",\"operation\",\"X-ray\"],\"answer\":\"operation\"},{\"id\":\"g-39\",\"type\":\"multiple-choice\",\"prompt\":\"She won a seat in parliament at the last ........ .\",\"options\":[\"general election\",\"opinion poll\",\"referendum\"],\"answer\":\"general election\"},{\"id\":\"g-40\",\"type\":\"multiple-choice\",\"prompt\":\"I’m surprised you didn’t get upset. If someone said that to me, _____ really angry.\",\"options\":[\"I’m\",\"I was\",\"I’d be\"],\"answer\":\"I’d be\"},{\"id\":\"g-41\",\"type\":\"multiple-choice\",\"prompt\":\"This used to be _____ part of the city, but since the old buildings were renovated it’s become a very fashionable area.\",\"options\":[\"an affluent\",\"a run-down\",\"a trendy\"],\"answer\":\"a run-down\"},{\"id\":\"g-42\",\"type\":\"multiple-choice\",\"prompt\":\"Cassie went to bed early because she was ........ .\",\"options\":[\"tired\",\"stressed\",\"relaxed\"],\"answer\":\"tired\"},{\"id\":\"g-43\",\"type\":\"multiple-choice\",\"prompt\":\"In the 1960s, computers were ........ expensive that ordinary people couldn’t afford them.\",\"options\":[\"so\",\"such\",\"too\"],\"answer\":\"so\"},{\"id\":\"g-44\",\"type\":\"multiple-choice\",\"prompt\":\"Do you want _____ the match tonight?\",\"options\":[\"watching\",\"watch\",\"to watch\"],\"answer\":\"to watch\"},{\"id\":\"g-45\",\"type\":\"multiple-choice\",\"prompt\":\"Researchers claim the new discovery is a major _____ in the fight against malaria.\",\"options\":[\"breakthrough\",\"investigation\",\"progress\"],\"answer\":\"breakthrough\"},{\"id\":\"g-46\",\"type\":\"multiple-choice\",\"prompt\":\"The Maths problem was really difficult and I just couldn’t _____ the answer.\",\"options\":[\"check in\",\"set off\",\"work out\"],\"answer\":\"work out\"},{\"id\":\"g-47\",\"type\":\"multiple-choice\",\"prompt\":\"When I was a child, I never _____ about the future.\",\"options\":[\"have worried\",\"used to worry\",\"was worrying\"],\"answer\":\"used to worry\"},{\"id\":\"g-48\",\"type\":\"multiple-choice\",\"prompt\":\"A local politician has _____ charges of corruption made by the opposition party.\",\"options\":[\"accused\",\"blamed\",\"denied\"],\"answer\":\"denied\"},{\"id\":\"g-49\",\"type\":\"multiple-choice\",\"prompt\":\"_____ worries me about society today is how completely we have come to depend on technology.\",\"options\":[\"That\",\"What\",\"Which\"],\"answer\":\"What\"},{\"id\":\"g-50\",\"type\":\"multiple-choice\",\"prompt\":\"Cats and dogs are usually kept as ........ .\",\"options\":[\"farm animals\",\"wild animals\",\"pets\"],\"answer\":\"pets\"}]},{\"id\":\"writing\",\"label\":\"Writing Placement Test\",\"durationMinutes\":20,\"selectionType\":\"single_choice\",\"requiredSelections\":1,\"instructions\":\"Choose ONE of these topics and write about it. Create 1 Essay based on your selected topic (20 minutes).\",\"topics\":[{\"id\":\"w-topic-1\",\"title\":\"Personal Profile\",\"type\":\"essay\",\"prompt\":\"Write a personal profile about yourself for a website where you can meet new Internet friends.\",\"guidingQuestions\":[\"What is your name, age, etc.?\",\"Where you are from, and what do you do?\",\"What do you look like, and what sort of person are you?\",\"What are your interests and your likes/dislikes?\",\"What sort of new friends do you want to meet?\"]},{\"id\":\"w-topic-2\",\"title\":\"Email to a Friend\",\"type\":\"essay\",\"prompt\":\"Write an email to a friend from another part of the world who wants to know more about your country. You can use your own ideas, and/or you can describe some of these things:\",\"guidingQuestions\":[\"How big the country is, where it is and what the land is like (forests, mountains, etc.)\",\"Main cities, famous landmarks and tourist attractions\",\"The local language(s) and culture\",\"What the people are like\",\"Traditional food, music, dances, etc. of your country\",\"You should finish your email by inviting your friend to visit your country some time so that they can see what it is like.\"]},{\"id\":\"w-topic-3\",\"title\":\"Childhood Memory\",\"type\":\"essay\",\"prompt\":\"Write about a strong childhood memory – for example, something that made you very happy or very frightened.\",\"guidingQuestions\":[\"Briefly explain how old you were and where you were, and tell the story of what happened.\",\"Try to remember details such as sounds, smells, colours and the weather, and describe these in your story.\",\"Explain how you felt and why you felt this way.\",\"How do you feel now about the event?\"]},{\"id\":\"w-topic-4\",\"title\":\"Film, Play, or Book Review\",\"type\":\"essay\",\"prompt\":\"Write a review of your favourite film, play or book.\",\"guidingQuestions\":[\"Explain what type of work it is (for example, a comedy film, a romantic novel, etc.)\",\"Say where and when the story takes place, and briefly describe what happens.\",\"Describe the main characters, and say whether you like or dislike each of them, and why.\",\"Try to explain why this work is your favourite.\"]},{\"id\":\"w-topic-5\",\"title\":\"Opinion Essay\",\"type\":\"essay\",\"prompt\":\"Write an article discussing whether you think our world is getting better or getting worse. You can use your own ideas, but you might like to include some of these issues:\",\"guidingQuestions\":[\"Medicine, scientific research, technology\",\"War, conflict between countries/groups\",\"Freedom and human rights\",\"Education, knowledge and skills\",\"Quality of life\",\"You should finish your article with a short conclusion summarising the main argument.\"]}],\"questions\":[{\"id\":\"w-topic-1\",\"title\":\"Personal Profile\",\"type\":\"essay\",\"prompt\":\"Write a personal profile about yourself for a website where you can meet new Internet friends.\",\"guidingQuestions\":[\"What is your name, age, etc.?\",\"Where you are from, and what do you do?\",\"What do you look like, and what sort of person are you?\",\"What are your interests and your likes/dislikes?\",\"What sort of new friends do you want to meet?\"]},{\"id\":\"w-topic-2\",\"title\":\"Email to a Friend\",\"type\":\"essay\",\"prompt\":\"Write an email to a friend from another part of the world who wants to know more about your country. You can use your own ideas, and/or you can describe some of these things:\",\"guidingQuestions\":[\"How big the country is, where it is and what the land is like (forests, mountains, etc.)\",\"Main cities, famous landmarks and tourist attractions\",\"The local language(s) and culture\",\"What the people are like\",\"Traditional food, music, dances, etc. of your country\",\"You should finish your email by inviting your friend to visit your country some time so that they can see what it is like.\"]},{\"id\":\"w-topic-3\",\"title\":\"Childhood Memory\",\"type\":\"essay\",\"prompt\":\"Write about a strong childhood memory – for example, something that made you very happy or very frightened.\",\"guidingQuestions\":[\"Briefly explain how old you were and where you were, and tell the story of what happened.\",\"Try to remember details such as sounds, smells, colours and the weather, and describe these in your story.\",\"Explain how you felt and why you felt this way.\",\"How do you feel now about the event?\"]},{\"id\":\"w-topic-4\",\"title\":\"Film, Play, or Book Review\",\"type\":\"essay\",\"prompt\":\"Write a review of your favourite film, play or book.\",\"guidingQuestions\":[\"Explain what type of work it is (for example, a comedy film, a romantic novel, etc.)\",\"Say where and when the story takes place, and briefly describe what happens.\",\"Describe the main characters, and say whether you like or dislike each of them, and why.\",\"Try to explain why this work is your favourite.\"]},{\"id\":\"w-topic-5\",\"title\":\"Opinion Essay\",\"type\":\"essay\",\"prompt\":\"Write an article discussing whether you think our world is getting better or getting worse. You can use your own ideas, but you might like to include some of these issues:\",\"guidingQuestions\":[\"Medicine, scientific research, technology\",\"War, conflict between countries/groups\",\"Freedom and human rights\",\"Education, knowledge and skills\",\"Quality of life\",\"You should finish your article with a short conclusion summarising the main argument.\"]}]},{\"id\":\"speaking\",\"label\":\"Oral Placement Test\",\"durationMinutes\":20,\"navigationType\":\"sequential_next_button\",\"instructions\":\"Answer each question orally. After answering a question, click \'Next Question\' to proceed to the next topic. You may continue through the 21 questions until all prompts are completed or the 20-minute time limit is reached[cite: 3].\",\"scoring\":{\"minScore\":1,\"maxScore\":5},\"questions\":[{\"id\":\"s-1\",\"type\":\"speaking-audio\",\"level\":\"Elementary\",\"topic\":\"Personal information\",\"prompt\":\"What’s your name? How do you spell it? Where do you live? What’s your phone number? What’s your email address?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-2\",\"type\":\"speaking-audio\",\"level\":\"Elementary\",\"topic\":\"Family\",\"prompt\":\"How many people are there in your family? Tell me about your parents / brothers or sisters / children. What are their names, ages, etc?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-3\",\"type\":\"speaking-audio\",\"level\":\"Elementary\",\"topic\":\"Home\",\"prompt\":\"Where are you from? What is your home town or city? Do (or did) you like living there? Is it: – big? – beautiful? – noisy? – clean?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-4\",\"type\":\"speaking-audio\",\"level\":\"Elementary\",\"topic\":\"Studies\",\"prompt\":\"What do (or did) you study? Is (or was) it: – interesting? – difficult? What will you do (or did you do) after finishing your studies?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-5\",\"type\":\"speaking-audio\",\"level\":\"Elementary\",\"topic\":\"Work\",\"prompt\":\"What job do you do (or want to do)? When did (or will) you start working? Why did (or do) you want to do this job?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-6\",\"type\":\"speaking-audio\",\"level\":\"Pre-Intermediate\",\"topic\":\"Appearance & character\",\"prompt\":\"Tell me about your best friend. Describe his/her appearance (e.g. colour of hair/eyes, height) and character (e.g. kind, funny). When did you meet?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-7\",\"type\":\"speaking-audio\",\"level\":\"Pre-Intermediate\",\"topic\":\"Weather\",\"prompt\":\"What’s the weather like today? Which is your favourite season? What is the weather like then? What weather makes you feel happy/sad/etc?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-8\",\"type\":\"speaking-audio\",\"level\":\"Pre-Intermediate\",\"topic\":\"Shopping\",\"prompt\":\"Do you enjoy shopping? How often do you go shopping? Do you go shopping alone or with friends? What sort of things do you usually buy?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-9\",\"type\":\"speaking-audio\",\"level\":\"Pre-Intermediate\",\"topic\":\"Sports & exercise\",\"prompt\":\"How much exercise do you do? Is exercise important? Why (not)? Do you like playing/watching sports? What sports do you like playing/watching?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-10\",\"type\":\"speaking-audio\",\"level\":\"Intermediate\",\"topic\":\"Food\",\"prompt\":\"Do you usually eat healthy meals? What is some of your favourite food? Do you like eating out (e.g. restaurants)? Why (not)? Do you like cooking?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-11\",\"type\":\"speaking-audio\",\"level\":\"Intermediate\",\"topic\":\"Animals\",\"prompt\":\"Do you like animals? What are some of your favourite animals? What pet(s) do you have (or would you like to have)? How do animals help people?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-12\",\"type\":\"speaking-audio\",\"level\":\"Intermediate\",\"topic\":\"Computers & gadgets\",\"prompt\":\"Do you often use computers, mp3 players, games consoles, etc? What do you mainly use the Internet for? What problems can computers/etc cause?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-13\",\"type\":\"speaking-audio\",\"level\":\"Intermediate\",\"topic\":\"Languages\",\"prompt\":\"What languages do you speak? Is it important to speak several languages? Why (not)? Is it a good or bad thing that most people in the world learn English?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-14\",\"type\":\"speaking-audio\",\"level\":\"Upper Intermediate\",\"topic\":\"Travel\",\"prompt\":\"Do you like to travel? Why (not)? What place would you most like to visit? Why? What’s your (least) favourite way to travel? Does travel really ‘broaden the mind’?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-15\",\"type\":\"speaking-audio\",\"level\":\"Upper Intermediate\",\"topic\":\"Crime\",\"prompt\":\"Is crime a problem in this (or your) country? What can be done to reduce crime? Are the laws in this (or your) country generally too strict, or not strict enough?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-16\",\"type\":\"speaking-audio\",\"level\":\"Upper Intermediate\",\"topic\":\"Careers\",\"prompt\":\"What sort of career do you want? What do you want most from it (e.g. money, creativity, etc)? Should a career be the most important thing in someone’s life?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-17\",\"type\":\"speaking-audio\",\"level\":\"Upper Intermediate\",\"topic\":\"Art, books, music etc.\",\"prompt\":\"How often do you listen to music, read a book, visit an exhibition? Do you play an instrument/paint/write/etc? Are art/music/etc important to society? Why (not)?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-18\",\"type\":\"speaking-audio\",\"level\":\"Advanced\",\"topic\":\"News & the media\",\"prompt\":\"How closely do you follow the news? Which media (e.g. TV, newspapers, online) cover the news best? Give examples. What will news media be like in the future?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-19\",\"type\":\"speaking-audio\",\"level\":\"Advanced\",\"topic\":\"Cities\",\"prompt\":\"Why do people choose to live in cities? What are the (dis)advantages of city life, compared to living in the countryside? Which do/would you prefer?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-20\",\"type\":\"speaking-audio\",\"level\":\"Advanced\",\"topic\":\"Man & nature\",\"prompt\":\"How do we affect nature (e.g. rainforests)? How does nature affect us (e.g. floods)? Will problems such as pollution or endangered species ever be solved?\",\"scoreRange\":[1,2,3,4,5]},{\"id\":\"s-21\",\"type\":\"speaking-audio\",\"level\":\"Advanced\",\"topic\":\"Society & culture\",\"prompt\":\"Do you often mix with people from a different culture to yours? Do you like or dislike this? What are the benefits and/or problems of a multicultural society?\",\"scoreRange\":[1,2,3,4,5]}]}]}', '2026-09-09T02:44:06.724Z'),
('rubrics_content', '{\"title\":\"Karya Bangsa Placement Detailed CEFR Rubrics\",\"version\":\"2026.2\",\"notice\":\"Grammar & Vocabulary is scored automatically mapped to CEFR. Writing and Speaking are evaluated by administrators using 1–6 CEFR criteria. Listening comprehension is integrated into audio-format Speaking prompts.\",\"bandScale\":{\"range\":\"A1–C2\",\"overall\":\"Writing and Speaking: 0–1 = A1, 2–3 = A2, 4–5 = B1, 6–7 = B2, 8–9 = C1, 10 = C2\"},\"grammarVocabulary\":{\"title\":\"GRAMMAR & VOCABULARY\",\"format\":\"50 Contextual Objective Items (1 point per item)\",\"thresholds\":\"A1: 0–18 | A2: 19–25 | B1: 26–32 | B2: 33–39 | C1: 40–46 | C2: 47–50\",\"scoreMapping\":[{\"score\":\"0 – 18 points\",\"level\":\"A1 (Elementary)\"},{\"score\":\"19 – 25 points\",\"level\":\"A2 (Pre-Intermediate)\"},{\"score\":\"26 – 32 points\",\"level\":\"B1 (Intermediate)\"},{\"score\":\"33 – 39 points\",\"level\":\"B2 (Upper Intermediate)\"},{\"score\":\"40 – 46 points\",\"level\":\"C1 (Advanced)\"},{\"score\":\"47 – 50 points\",\"level\":\"C2 (Higher Level Series Recommended)\"}],\"criteria\":[{\"name\":\"Complex Syntactic Control\",\"description\":\"Mastery of sentence structures including subjunctive mood, inverted conditionals, relative clauses, and passive constructions.\"},{\"name\":\"Collocational & Register Precision\",\"description\":\"Accurate deployment of formal academic collocations, prepositions, phrasal verbs, and appropriate institutional register.\"},{\"name\":\"Morphological Accuracy\",\"description\":\"Precision in word formation, derivational prefixes/suffixes, subject-verb concord, and tense/aspect consistency.\"}]},\"writing\":{\"title\":\"WRITING\",\"format\":\"2 Tasks: Memo (120–150 words) and Discursive Essay (180–220 words) (20 Mins)\",\"weight\":\"Administrator scores each of 4 criteria from (A1) to (C2).\",\"reviewNote\":\"Evaluators grade responses against CEFR descriptors (1=A1, 2=A2, 3=B1, 4=B2, 5=C1).\",\"levels\":[{\"score\":\"0–1\",\"level\":\"A1\",\"descriptors\":[\"The topic is not developed at all, and writing seems to take enormous effort.\",\"The purpose of the text and the writer’s aim are entirely unclear.\",\"The text is not organised at either the paragraph or sentence level.\",\"There is insufficient language control to express even very simple ideas.\",\"There are very many errors in the use of language and standard writing conventions.\",\"There is little or no use of appropriate vocabulary and structures.\"]},{\"score\":\"2–3\",\"level\":\"A2\",\"descriptors\":[\"The topic is not well developed, and writing seems to take considerable effort.\",\"The purpose of the text and the writer’s aim are generally unclear.\",\"The text is not well organised at either the paragraph or sentence level.\",\"There is insufficient language control to express relatively simple ideas.\",\"There are many errors in the use of language and standard writing conventions.\",\"There is very limited use of appropriate vocabulary and structures.\"]},{\"score\":\"4–5\",\"level\":\"B1\",\"descriptors\":[\"The topic is quite well developed, although writing seems to take some effort.\",\"The purpose of the text and the writer’s aim are not entirely clear.\",\"The text is reasonably well organised, at least at the sentence level.\",\"There is usually sufficient language control to express simple ideas.\",\"There are some errors in the use of language and standard writing conventions.\",\"There is limited use of appropriate vocabulary and structures.\"]},{\"score\":\"6–7\",\"level\":\"B2\",\"descriptors\":[\"The topic is well developed, and writing seems to take little effort.\",\"The purpose of the text and the writer’s aim are generally clear.\",\"The text is reasonably well organised at both the sentence and paragraph level.\",\"There is sufficient language control to express simple ideas.\",\"There are a few errors in the use of language and standard writing conventions.\",\"The text contains a range of appropriate vocabulary and structures.\"]},{\"score\":\"8–9\",\"level\":\"C1\",\"descriptors\":[\"The topic is very well developed, and writing seems to take very little effort.\",\"The purpose of the text and the writer’s aim are clear.\",\"The text is well organised at both the sentence and paragraph level.\",\"There is sufficient language control to express some quite complex ideas.\",\"There are few errors in the use of language and standard writing conventions.\",\"The text contains quite a wide range of appropriate vocabulary and structures.\"]},{\"score\":\"10\",\"level\":\"C2\",\"descriptors\":[\"The topic is fully developed, and writing seems effortless.\",\"The purpose of the text and the writer’s aim are perfectly clear.\",\"The text is extremely well organised at both the sentence and paragraph level.\",\"There is sufficient language control to express a range of complex ideas.\",\"There are almost no errors in the use of language and standard writing conventions.\",\"The text contains a wide range of appropriate vocabulary and structures.\"]}],\"criteria\":[{\"name\":\"Task Achievement\",\"description\":\"How fully the essay addresses all elements of the prompt, sustains a focused pedagogical thesis, and substantiates claims with concrete examples.\"},{\"name\":\"Coherence and Cohesion\",\"description\":\"Clarity of essay structure, logical paragraph progression, effective use of transitional cohesive devices, and flow of argumentation.\"},{\"name\":\"Lexical Resource\",\"description\":\"Range, precision, sophistication, and stylistic appropriateness of academic vocabulary with minimal lexical inaccuracies.\"},{\"name\":\"Grammatical Range and Accuracy\",\"description\":\"Flexibility and accuracy of complex clause structures, punctuation mastery, grammatical control, and syntactic variety.\"}]},\"speaking\":{\"title\":\"SPEAKING\",\"format\":\"2-Part Recorded Audio/Video Interview with Audio-Format Prompts (20 Mins)\",\"weight\":\"Administrator scores each of 4 criteria from (A1) to (C2).\",\"reviewNote\":\"Evaluators review recorded video and audio streams to evaluate oral fluency, auditory prompt comprehension, grammatical control, and communicative efficacy.\",\"passingRules\":{\"lulusLevel\":\"Siswa berhasil mendapatkan skor minimal 3 (Good) pada pertanyaan di tingkat tersebut.\",\"belumMampu\":\"Siswa mendapatkan skor 1 (Low) atau 2 (Fair) saat mencoba pertanyaan di tingkat berikutnya.\"},\"levels\":[{\"score\":1,\"level\":\"Low\",\"descriptors\":[\"Speaks with frequent hesitation; occasionally does not respond verbally.\",\"Rarely responds with confidence; frequently reluctant to use the language.\",\"Speech and pronunciation are usually not easily understood.\",\"Rarely uses complete sentences and phrases appropriately.\",\"Rarely or never uses colloquial expressions appropriately.\",\"Rarely uses appropriate and varied vocabulary.\",\"Makes numerous errors in form or function.\"]},{\"score\":2,\"level\":\"Fair\",\"descriptors\":[\"Speaks with frequent hesitation.\",\"Rarely responds with confidence; often reluctant to use the language.\",\"Speech and pronunciation are frequently not easily understood.\",\"Occasionally uses complete sentences and phrases appropriately.\",\"Uses very few colloquial expressions appropriately.\",\"Occasionally uses appropriate and varied vocabulary.\",\"Makes frequent errors in form or function.\"]},{\"score\":3,\"level\":\"Good\",\"descriptors\":[\"Speaks fluently with a little hesitation.\",\"Usually responds with confidence.\",\"Speech and pronunciation may not always be easily understood.\",\"Generally uses complete sentences and phrases appropriately.\",\"Uses a few colloquial expressions appropriately.\",\"Uses appropriate and varied vocabulary on most occasions.\",\"Makes occasional errors in form or function.\"]},{\"score\":4,\"level\":\"Very Good\",\"descriptors\":[\"Speaks fluently without much hesitation.\",\"Almost always responds with confidence.\",\"Speech and pronunciation are almost always clear and easily understood.\",\"Almost always uses complete sentences and phrases appropriately.\",\"Uses a number of colloquial expressions appropriately.\",\"Almost always uses appropriate and varied vocabulary.\",\"Makes few errors in form or function.\"]},{\"score\":5,\"level\":\"Excellent\",\"descriptors\":[\"Speaks fluently without hesitation.\",\"Consistently responds with confidence.\",\"Speech and pronunciation are always clear and easily understood.\",\"Consistently uses complete sentences and phrases appropriately.\",\"Uses a wide range of colloquial expressions appropriately.\",\"Consistently uses appropriate and varied vocabulary.\",\"Makes very few or no errors in form or function.\"]}],\"criteria\":[{\"name\":\"Fluency and Spontaneity\",\"description\":\"Natural speech rhythm, appropriate speaking rate, smooth transition between ideas, and effective hesitation management.\"},{\"name\":\"Listening Comprehension & Interaction\",\"description\":\"Accurate comprehension of spoken prompts, relevant topic engagement, and coherent communicative response.\"},{\"name\":\"Lexical & Idiomatic Range\",\"description\":\"Breadth, precision, and nuance of vocabulary used to discuss educational methodologies and abstract pedagogical issues.\"},{\"name\":\"Grammatical Complexity & Pronunciation\",\"description\":\"Accurate use of varied sentence structures, tense coordination, natural sentence intonation contours, and clear articulation.\"}]}}', '2026-09-08T14:21:45.057Z'),
('system_settings', '{\"durationMinutes\":70,\"allowResume\":true,\"autosaveIntervalSeconds\":30,\"requireCameraAudio\":true,\"maxAudioPlayCount\":2,\"passingBand\":\"6.5\",\"provisionalScoringAuto\":true,\"certificateIssuer\":\"Pusat Bahasa & Asesmen Karya Bangsa\",\"schoolName\":\"Karya Bangsa School\",\"schoolDomain\":\"karyabangsa.sch.id\",\"supportEmail\":\"muhammadazzikra@karyabangsa.sch.id\",\"enforceTeacherWhitelist\":true,\"enforceUnitMatch\":true,\"maintenanceMode\":false,\"maintenanceMessage\":\"Assessify is currently undergoing scheduled maintenance. Candidate assessments will resume shortly.\",\"sessionTimeoutHours\":12,\"antiCheat\":{\"enabled\":true,\"tabSwitchDetection\":true,\"requireFullscreen\":true,\"splitScreenDetection\":true,\"blockDevTools\":true,\"blockCopyPaste\":true},\"updatedAt\":\"2026-09-09T02:57:01.716Z\",\"updatedBy\":\"azzikra\",\"gemini_model\":\"gemini-3.6-flash\"}', '2026-09-09T02:57:01.717Z');

